function osfrRequest(int $port,string $method,string $path,array $form,array &$cookies):array
{
    $content=$form===[]?'':http_build_query($form);$headers=['Host: fmonitor.example.test','Connection: close'];
    if($cookies)$headers[]='Cookie: '.implode('; ',array_map(static fn($k,$v)=>"$k=$v",array_keys($cookies),$cookies));
    if($content!=='')$headers[]='Content-Type: application/x-www-form-urlencoded';
    $context=stream_context_create(['http'=>['ignore_errors'=>true,'follow_location'=>0,'method'=>$method,'header'=>implode("\r\n",$headers),'content'=>$content]]);
    $body=file_get_contents("http://127.0.0.1:$port$path",false,$context);$raw=$http_response_header??[];$result=[];
    foreach(array_slice($raw,1)as$line){$at=strpos($line,':');if($at!==false)$result[strtolower(substr($line,0,$at))][]=trim(substr($line,$at+1));}
    foreach($result['set-cookie']??[]as$cookie)if(preg_match('/^([^=;]+)=([^;]*)/',$cookie,$m))$cookies[$m[1]]=$m[2];
    preg_match('#^HTTP/\S+ (\d+)#',$raw[0]??'',$m);return[(int)($m[1]??0),$result,(string)$body];
}
function osfrCsrf(string $html):string{if(!preg_match('/name="_csrf" value="([^"]+)"/',$html,$m))throw new TestFailure('SETUP_FAILURE: csrf');return html_entity_decode($m[1],ENT_QUOTES|ENT_HTML5,'UTF-8');}
