    $db->query("INSERT INTO `{$p}fm2_pilot_otiz_snapshot_objects`(snapshot_id,object_id,regnumber,address,previous_progress_bp,current_progress_bp,progress_fact_date,premium_cents,shaft_bp,kss_bp,accrued_cents,fund_cents,closed_before_cents,remaining_cents,pool_cents,distributed_cents,undistributed_cents,calculation_state,inputs_json)VALUES($id,$object,'REC-$object','Recovery object $object',0,10000,'2026-09-24',1000000000000,10000,10000,1000000000000,1000000000000,0,1000000000000,1000000000000,1000000000000,0,'ready','{}')");
}
function osfrInventory(mysqli $db,string $p):string
{
    $tables=['fm2_pilot_otiz_snapshots','fm2_pilot_otiz_snapshot_objects','fm2_pilot_otiz_payment_closures','fm2_pilot_otiz_events','fm2_otiz_settlement_operations','fm2_jobs','fm2_outbox'];$all=[];
    foreach($tables as$table){$exists=$db->query("SHOW TABLES LIKE '{$p}{$table}'")->num_rows===1;$all[$table]=$exists?$db->query("SELECT * FROM `{$p}{$table}` ORDER BY 1")->fetch_all(MYSQLI_ASSOC):[];}
    return hash('sha256',json_encode($all,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
}
function osfrAssertAbsent(array $needles,array $headers,string $body,string $message):void
